-- 12-official-plays. Reviewed uploaded workbook only; save pending edits and back up first.
-- Run ENTIRE file in DB Browser, verify counts, then Write Changes.
-- SAVEPOINT supports an existing transaction. No records are replaced.
-- 9575 official plays; OLDPlayHistory excluded; original play IDs unchanged.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_remaining_12;
CREATE TEMP TABLE afl_remaining_12_0 AS SELECT id, game_id, sequence, period_before, seconds_before, period_after, seconds_after, offense_team_id, defense_team_id, down_before, distance_before, ball_before, down_after, distance_after, ball_after, drive_start, play_type, yards, air_yards, yac, result, defense_result, is_complete, is_sack, is_first_down, is_touchdown, is_safety, is_fumble, fumble_lost, is_turnover, turnover_type, home_score_after, away_score_after, description_raw FROM plays WHERE 0;
CREATE TEMP TABLE afl_remaining_12_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_remaining_12_check BEFORE INSERT ON afl_remaining_12_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM seasons WHERE id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Import 05 season first.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM schema_migrations WHERE version=2) THEN RAISE(ROLLBACK,'Apply schema upgrade 10 first.') END;
 SELECT CASE WHEN (SELECT count(*) FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND status='final')<>70 THEN RAISE(ROLLBACK,'Import all final games (09) first.') END;
 SELECT CASE WHEN (SELECT count(*) FROM players WHERE league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd')<107 THEN RAISE(ROLLBACK,'Import player identities first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_12_0 i JOIN plays t ON t.id=i.id WHERE t.game_id IS NOT i.game_id OR t.sequence IS NOT i.sequence OR t.period_before IS NOT i.period_before OR t.seconds_before IS NOT i.seconds_before OR t.period_after IS NOT i.period_after OR t.seconds_after IS NOT i.seconds_after OR t.offense_team_id IS NOT i.offense_team_id OR t.defense_team_id IS NOT i.defense_team_id OR t.down_before IS NOT i.down_before OR t.distance_before IS NOT i.distance_before OR t.ball_before IS NOT i.ball_before OR t.down_after IS NOT i.down_after OR t.distance_after IS NOT i.distance_after OR t.ball_after IS NOT i.ball_after OR t.drive_start IS NOT i.drive_start OR t.play_type IS NOT i.play_type OR t.yards IS NOT i.yards OR t.air_yards IS NOT i.air_yards OR t.yac IS NOT i.yac OR t.result IS NOT i.result OR t.defense_result IS NOT i.defense_result OR t.is_complete IS NOT i.is_complete OR t.is_sack IS NOT i.is_sack OR t.is_first_down IS NOT i.is_first_down OR t.is_touchdown IS NOT i.is_touchdown OR t.is_safety IS NOT i.is_safety OR t.is_fumble IS NOT i.is_fumble OR t.fumble_lost IS NOT i.fumble_lost OR t.is_turnover IS NOT i.is_turnover OR t.turnover_type IS NOT i.turnover_type OR t.home_score_after IS NOT i.home_score_after OR t.away_score_after IS NOT i.away_score_after OR t.description_raw IS NOT i.description_raw) THEN RAISE(ROLLBACK,'plays: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_12_0 i JOIN plays t ON t.game_id=i.game_id AND t.sequence=i.sequence WHERE NOT (t.id=i.id)) THEN RAISE(ROLLBACK,'plays: natural key uses another ID.') END;
END;
DROP TRIGGER afl_remaining_12_check;
DROP TABLE afl_remaining_12_guard;
DROP TABLE afl_remaining_12_0;
RELEASE SAVEPOINT afl_remaining_12;
PRAGMA foreign_key_check;
SELECT 'plays' AS imported_table,count(*) AS reviewed_records_present FROM plays t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='9d0614b3-f458-5472-ba50-0623e8d24707' AND m.target_table='plays' AND m.target_id=CAST(t.id AS TEXT));
